import { Chat } from '@tale-ui/react/chat';
import { Button } from '@tale-ui/react/button';
import { TextArea } from '@tale-ui/react/text-area';

export function Conversation() {
  return (
    <Chat.Root aria-label="Support conversation">
      <Chat.List aria-label="Messages">
        <Chat.Message speaker="user" aria-label="User message">
          <Chat.Bubble>Find the setup guide.</Chat.Bubble>
        </Chat.Message>
        <Chat.Message speaker="assistant" aria-label="Assistant message">
          <Chat.Bubble>I found the setup guide.</Chat.Bubble>
          <Chat.ToolCall state="success" label="Search docs" statusLabel="Complete">
            One result
          </Chat.ToolCall>
        </Chat.Message>
      </Chat.List>
      <Chat.Composer aria-label="Message composer" onSubmit={(event) => event.preventDefault()}>
        <TextArea.Root aria-label="Message" />
        <Button type="submit">Send</Button>
      </Chat.Composer>
    </Chat.Root>
  );
}
